script:
(function () {
  'use strict';
  // Long-term care cost projection. You enter today's local prices; nothing is hard-coded.
  //   annual cost today: in-home care = hourly rate x hours a week x 52; adult day care = daily
  //   rate x days a week x 52; assisted living = monthly x 12; nursing home = daily x 365.
  //   cost in care year k (k = 0, 1, ...) = annual cost today x (1 + inflation)^(years until care + k)
  //   (a final part-year counts pro rata). Insurance pays, while its benefit period lasts,
  //   min(cost, monthly benefit x 12 x (1 + benefit growth)^(years until care + k)).
  // Savings grow at the return until care starts, pay the uncovered cost at the start of each
  // care year and keep growing between years. Anything left unpaid is the unprotected need.
  // Set aside today = sum of uncovered costs discounted at the savings return, minus savings.
  // CHECKS (Node, scratch tests): $5,500/month assisted living, 0% inflation, 3 years starting
  // now -> $198,000; 3% inflation, care in 20 years for 3 years -> 66,000 x 1.03^20 x
  // (1 + 1.03 + 1.03^2) = $368,445.61; insurance $3,000/month
  // for 2 years on that -> $72,000 covered at 0% benefit growth; savings equal to the computed
  // "set aside today" leave a $0 shortfall; 2.5 years -> last year counts half.
  var TYPES = [
    { key: 'home', name: 'In-home care' },
    { key: 'day', name: 'Adult day care' },
    { key: 'assisted', name: 'Assisted living' },
    { key: 'nursing', name: 'Nursing home' }
  ];

  function annualCosts(c) {
    return { home: c.homeRate * c.homeHours * 52, day: c.dayRate * c.dayDays * 52,
             assisted: c.assistedMonthly * 12, nursing: c.nursingDaily * 365 };
  }

  // p: annual (today's cost), yearsUntil, years, inflation, funds, ret, benefit (monthly),
  // benefitYears, benefitGrowth (decimals)
  function project(p) {
    var rows = [], bal = p.funds * Math.pow(1 + p.ret, p.yearsUntil), startBal = bal;
    var total = 0, insured = 0, fromSavings = 0, short = 0, neededToday = 0;
    var n = Math.ceil(p.years - 1e-9);
    for (var k = 0; k < n; k++) {
      var f = Math.min(1, p.years - k);
      var t = p.yearsUntil + k;
      var annual = p.annual * Math.pow(1 + p.inflation, t);
      var cost = annual * f;
      var insFrac = Math.max(0, Math.min(f, p.benefitYears - k));
      var ins = insFrac * Math.min(annual, p.benefit * 12 * Math.pow(1 + p.benefitGrowth, t));
      var need = cost - ins;
      var pay = Math.min(need, bal);
      bal -= pay;
      total += cost; insured += ins; fromSavings += pay; short += need - pay;
      neededToday += need / Math.pow(1 + p.ret, t);
      rows.push({ k: k, cost: cost, ins: ins, savings: pay, short: need - pay, balance: bal });
      if (k < n - 1) bal *= 1 + p.ret;
    }
    return { rows: rows, total: total, insured: insured, fromSavings: fromSavings, short: short, startBal: startBal,
             left: bal, firstYear: p.annual * Math.pow(1 + p.inflation, p.yearsUntil),
             setAside: Math.max(0, neededToday - p.funds) };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fillRows(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  function update() {
    var age = num('ltAge'), startAge = num('ltStart'), years = num('ltYears'), type = document.getElementById('ltType').value;
    var c = { homeRate: num('ltHomeRate'), homeHours: num('ltHomeHours'), dayRate: num('ltDayRate'), dayDays: num('ltDayDays'),
              assistedMonthly: num('ltAssisted'), nursingDaily: num('ltNursing') };
    var inflation = num('ltInflation'), funds = num('ltFunds'), ret = num('ltReturn'),
        benefit = num('ltBenefit'), benefitYears = num('ltBenefitYears'), benefitGrowth = num('ltBenefitGrowth');
    var all = [age, startAge, years, c.homeRate, c.homeHours, c.dayRate, c.dayDays, c.assistedMonthly, c.nursingDaily,
               inflation, funds, ret, benefit, benefitYears, benefitGrowth];
    var error = document.getElementById('ltError');
    var msg = '';
    if (all.some(isNaN) || all.some(function (v) { return v < 0; })) msg = 'Enter non-negative numbers in every field.';
    else if (age > 110 || startAge < age || startAge > 110) msg = 'The age care starts must be between your current age and 110.';
    else if (years <= 0 || years > 30) msg = 'Enter between 0.5 and 30 years of care.';
    else if (c.homeHours > 168 || c.dayDays > 7) msg = 'Enter up to 168 hours and 7 days a week.';
    else if (inflation > 20 || ret > 20 || benefitGrowth > 20) msg = 'Enter rates from 0 to 20%.';
    else if (benefitYears > 50) msg = 'Enter a benefit period of up to 50 years.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }
    var costs = annualCosts(c), yearsUntil = startAge - age;
    var base = { yearsUntil: yearsUntil, years: years, inflation: inflation / 100, funds: funds, ret: ret / 100,
                 benefit: benefit, benefitYears: benefitYears, benefitGrowth: benefitGrowth / 100 };
    function run(key) { base.annual = costs[key]; return project(base); }
    var r = run(type);
    var label = TYPES.filter(function (t) { return t.key === type; })[0].name;
    set('ltTotalLabel', label + ': total cost of care');
    set('ltTotal', money(r.total));
    set('ltFirst', money(r.firstYear));
    set('ltInsured', money(r.insured));
    set('ltFromSavings', money(r.fromSavings));
    set('ltShort', money(r.short));
    set('ltSetAside', money(r.setAside));
    set('ltSummary', 'Care starts in ' + (yearsUntil === 0 ? 'the first year' : yearsUntil + (yearsUntil === 1 ? ' year' : ' years')) +
        ', at age ' + startAge + '. Your savings would be worth about ' + money(r.startBal) + ' by then' +
        (r.left > 0.5 ? ', with ' + money(r.left) + ' left after the care period.' : '.'));
    fillRows('ltTypes', TYPES.map(function (t) {
      var x = run(t.key);
      return [t.name, money(costs[t.key]), money(x.firstYear), money(x.total)];
    }));
    fillRows('ltSchedule', r.rows.map(function (row) {
      return [String(Math.round((startAge + row.k) * 100) / 100), money(row.cost), money(row.ins), money(row.savings),
              money(row.short), money(row.balance)];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ltForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
